pub(super) fn lookup(lang: Language, key: &str) -> Option<&'static str> {
    let idx = match lang {
        Language::En => 0,
        Language::Tr => 1,
        Language::Fr => 2,
        Language::De => 3,
        Language::Es => 4,
        Language::ZhTw => 5,
        Language::Vi => 6,
    };
    STRINGS.iter().find(|(k, _)| *k == key).map(|(_, v)| {
        if v[idx].is_empty() {
            v[0]
        } else {
            v[idx]
        }
    })
}
